section.programlisting:
{
  network: {
    connections: [
      {
        id: "Ethernet device 1",
        method4: "auto",
      },
      {
        id: "Wireless device 1",
        method4: "auto",
        wireless: {
          ssid: "HOME_NETWORK",
          password: "secret",
          security: "wpa-psk",
          mode: "infrastructure"
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "Wired connection 1",
        match: {
          interface: ["eth0"]
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "Wired connection 1",
        match: {
          driver: ["e1000e"]
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "Wired connection 1",
        match: {
          path: ["pci-0000:04:00.0"]
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "Wireless device 1",
        method4: "auto",
        method6: "disabled",
        interface: "wlan0",
        addresses: [
          "192.168.122.100/24"
        ],
        wireless: {
          ssid: "HOME_NETWORK",
          password: "secret",
          security: "wpa-psk",
          mode: "infrastructure"
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "Bridge0",
        interface: "br0",
        bridge: {
          ports: ["eth0", "eth1"]
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "Bond0",
        interface: "bond0",
        bond: {
          ports: ["eth0", "eth1"],
          mode: "active-backup",
          options: "primary=eth1"
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "vlan10",
        method4: "manual",
        method6: "disabled",
        status: "up",
        persistent: true,
        addresses: ["192.168.1.28/24"],
        gateway4: "192.168.1.1",
        nameservers: ["192.168.1.1"],
        vlan: {
          id: 10,
          parent: "eth0"
        }
      }
    ]
  }
}

{
  network: {
    connections: [
      {
        id: "default",
        status: "removed"
      },
      {
        id: "enp1s0",
        interface: "enp1s0",
        status: "up"
      }
    ]
  }
}
